        "content": "### 1. 從勞力密集邁向高科技島\n- **轉型背景**：1970 年代末期臺灣勞工薪資上漲，傳統代工失去低成本優勢，必須升級為高附加價值的技術密集產業。\n- **臺灣科技島雙推手（★ 獅湖114／大墩113 必考）**：\n  - **李國鼎**：有**「臺灣科技之父」**之稱，規劃加工出口區並推動設立**新竹科學園區**，力挺半導體發展。\n  - **張忠謀**：克服萬難創立**台積電（TSMC）**，首創專業**晶圓代工**模式，成為今日全球最大晶圓代工廠與「護國神山」。\n- **臺灣科學園區分佈與發展**：\n  - **民國 69 年（1980 年）**：在**「新竹市」**成立全臺第一座科學園區——**新竹科學園區**（鄰近**清華大學、陽明交通大學**產學合作培育人才，有「臺灣矽谷」美稱）。\n  - **區域平衡**：政府陸續增設**南部科學園區（南科）**、**中部科學園區（中科）**，三大園區皆位於**臺灣西部**（東部最少）。\n- **土地利用衝突與產業轉型真實案例**：\n  - **苗栗後龍「灣寶社區」**：農民抗爭反對良田劃入後龍科技園區，喊出*「我要農地，不要科技」*，凸顯產業擴張與農地／環境保護的衝突。\n  - **高雄煉油廠轉型**：前身為日治時期「高雄海軍第六燃料廠」，民國 80 年後因環保意識與產業轉型於西元 2015 年停產整治，現成功轉型為引進半導體與電動車產業的**「楠梓產業園區」**（不是文化園區）。\n\n### 2. 「代工產業」vs「MIT 自我品牌」辨析（★ 9 校選擇題常考！）\n\n| 產業型態 | 運作模式 | 代表企業與案例 | 優缺點比較 |\n| :--- | :--- | :--- | :--- |\n| **代工產業**<br>(OEM / ODM) | 依國外品牌客戶訂單規格生產產品，**由客戶負責掛牌銷售** | • 早期：**Nike、adidas** 品牌球鞋由臺灣製鞋工廠代工製造。<br>• 現代高科技：**台積電（TSMC）**為蘋果、輝達代工製造晶片。 | **優點**：訂單穩定、累積精密製造技術。<br>**限制**：利潤較低、容易被低薪國家搶單。 |\n| **建立自我品牌**<br>(MIT 品牌) | 自行研發設計並**掛上自有品牌直接行銷全球**，掌握品牌價值與定價權 | • 自行車：**捷安特（GIANT）、美利達（MERIDA）**<br>• 資通訊電腦：**華碩（ASUS）、宏碁（ACER）** | 提高產品附加價值與國際競爭力（⚠️ Nike、adidas、蘋果手機是外國品牌，台積電是晶圓代工，皆非消費性自我品牌考題正解！） |\n\n- **臺灣產業聚落速查**：**臺中市**擁有最密集的機械設備與五金製造業，是全臺最大的**機械產業聚落**；宜蘭冬山鄰近**南方澳漁港**，多魚鬆等水產加工廠。"
