        "content": "### 1. 都市 vs 鄉村特色與「生活圈」形成\n- **都市與鄉村相互依賴**：\n  - **都市優勢**：工作與就業機會多、交通運輸便捷、醫療中心（醫學中心）與高等教育（大專校院）資源集中。\n  - **鄉村優勢**：自然生態與耕地面積廣闊、提供農林漁牧食物原料（如蔬菜水果、魚產）及休閒觀光與土地空間。\n  - ⚠️ **防雷觀念**：產業並非只限於都市！都市高地價也會使部分工廠外移到鄉村或郊區（如食品加工廠看重原料豐富、空間廣闊與交通方便）。\n- **生活圈**：鄰近縣市透過便利的交通網絡往來密切，在食衣住行育樂滿足彼此需求，形成共同生活圈（例如**北北基桃生活圈**颱風同步停班停課、**中彰投生活圈**共享資源）。\n- **全臺人口分布現況**：臺灣近 **80%** 人口居住於都市；**新北市**為全臺人口最多縣市；臺北市人口外移第一大去處就是**新北市**（主因：**距離近、捷運公車通勤方便、房價比臺北市相對便宜**）。\n\n### 2. 陸海空運輸選擇與重大交通建設「雙面影響」（★ 9 校素養題必考）\n- **跨縣市交通工具最適搭配**：\n  - 北高（南港 ➔ 左營）當日快速往返：搭**高鐵**。\n  - 鄉村大量新鮮蔬果運至都市：走**高速公路（貨車陸運）**。\n  - 高雄大批冷凍貨櫃／重物運至澎湖：搭**海運航線（輪船）**。\n  - 金門／離島緊急重症病患後送臺北：搭**空運航線（航空醫療後送）**。\n- **交通建設的雙面刃**：\n\n| 重大交通建設 | 正面效益 ✅ | 負面衝擊與隱憂 ⚠️ |\n| :--- | :--- | :--- |\n| **國道 6 號**（臺中 ➔ 南投埔里） | 大幅縮短往返南投山區（如清境農場）時間、帶動觀光、增加草屯等地住宿/轉乘商機 | 假日車潮塞車、部分過路小鎮商業沒落、山區景觀環境髒亂與開發壓力 |\n| **雪山隧道**（國道 5 號，臺北 ➔ 宜蘭） | 大幅縮短**臺北到宜蘭**車程（⚠️ 不是宜蘭到花蓮！），促進宜蘭觀光與通勤 | 宜蘭農地轉建民宿農舍、假日雪隧大塞車與環境污染 |\n| **TPASS 行政院通勤月票** | **民國 112 年**推出，提供跨縣市公共運輸優惠價格（搭捷運/台鐵/公車/YouBike），減輕通勤族負擔並減碳 | ⚠️ 金門、馬祖等離島目前無跨縣市陸運路網適用 |"
