        "content": "### 1️⃣ 戰後臺灣經濟起飛 5 步驟排序（9 校有 8 校必考！）\n> **口訣：日治糖廠大圳 ➔ 民38~42 土地改革（減租/放領/耕者）➔ 民45 美援石門水庫/輕工業 ➔ 民55 高雄加工出口區 ➔ 民62 十大建設 ➔ 民69 新竹科學園區**\n\n1. *(前傳・日治時期)*：設立新式糖廠、興建**嘉南大圳**。\n2. **民國 38～42 年（40年代初）**：**土地改革**（三七五減租 ➔ 公地放領 ➔ 耕者有其田），地主補償金轉投資工商業。\n3. **民國 40～50 年代初**：**美援**（麵粉、棉花、黃豆、奶粉；**石門水庫**、中橫公路）與發展**紡織／食品罐頭等民生輕工業**。\n4. **民國 55 年（1966年）**：設全球第一座**高雄前鎮加工出口區**（後擴及楠梓、潭子；**2021 年更名科技產業園區**），女性大量投入職場。\n5. **民國 62 年（1973年）**：因應西亞**石油危機**推動**十大建設**（交通6＋重工3＋核能1）。\n6. **民國 69 年（1980年）**：設立**新竹科學園區**（李國鼎規劃、張忠謀創**台積電**），邁向科技島與建立 **MIT 自創品牌**（捷安特、美利達、華碩、宏碁）。"
